<?php $filterData=$discoveryOptions??[];foreach(['topic'=>['موضوع',$filterData['topics']??[]],'issue'=>['برچسب مسئله',$filterData['issues']??[]],'org_type'=>['نوع مجموعه',$filterData['types']??[]],'audience'=>['مخاطب تجربه',$filterData['audiences']??[]]] as $filterKey=>[$filterLabel,$filterOptions]):$filterChosen=\Morshed\Product\DiscoveryFilters::values($_GET,$filterKey,$filterKey!=='org_type'); ?>
<details class="dimension-filter" data-dimension="<?= $filterKey ?>" <?= $filterChosen?'open':'' ?>><summary><?= $filterLabel ?><?= $filterChosen?' · '.$this->number(count($filterChosen)):'' ?></summary><label class="sr-only" for="filter-search-<?= $filterKey ?>">جست‌وجوی <?= $filterLabel ?></label><input id="filter-search-<?= $filterKey ?>" type="search" data-option-search placeholder="جست‌وجو در <?= $filterLabel ?>"><div class="dimension-options">
<?php foreach($filterOptions as $option): ?><label <?= $filterKey==='organization_id'?'data-org-type="'.$this->h($option['org_type']).'"':'' ?>><input type="checkbox" name="<?= $filterKey ?>[]" value="<?= $this->h($option['id']) ?>" <?= in_array($option['id'],$filterChosen,true)?'checked':'' ?>><span><?= $this->h($option['path_title']??$option['name']??$option['title']) ?><?php if($filterKey==='audience'): ?><small> · <?= \Morshed\Product\Classifications::FAMILIES[$option['family']] ?></small><?php endif; ?></span></label><?php endforeach; ?>
<?php if(!$filterOptions): ?><p class="small muted">هنوز موردی در تجربه‌های منتشرشده ثبت نشده است.</p><?php endif; ?></div></details><?php endforeach; ?>
